def filter_even(numbers):
    output_filename = "filtered_numbers.txt"
    temp_odd_filename = "temp_odd.txt"
    temp_even_filename = "temp_even.txt"
    input_filename = "input_numbers.txt"

    f_in = open(input_filename, 'w')
    try:
        for num in numbers:
            f_in.write(str(num) + '\n')
    finally:
        f_in.close()

    even_numbers = []
    f_in = open(input_filename, 'r')
    try:
        f_even = open(temp_even_filename, 'w')
        try:
            f_odd = open(temp_odd_filename, 'w')
            try:
                for line in f_in:
                    num = int(line.strip())
                    if num % 2 == 0:
                        f_even.write(str(num) + '\n')
                    else:
                        f_odd.write(str(num) + '\n')
            finally:
                f_odd.close()
        finally:
            f_even.close()
    finally:
        f_in.close()

    f_even = open(temp_even_filename, 'r')
    try:
        for line in f_even:
            even_numbers.append(int(line.strip()))
    finally:
        f_even.close()

    f_out = open(output_filename, 'w')
    try:
        for num in even_numbers:
            f_out.write(str(num) + '\n')
    finally:
        f_out.close()

    return even_numbers

