def fibonacci_sequence(n):
    if n <= 0:
        with open("empty_sequence.txt", "w") as f_empty:
            f_empty.write("No Fibonacci numbers requested.")
        return []
    elif n == 1:
        with open("first_number.txt", "w") as f_one:
            f_one.write("0")
        return [0]
    else:
        sequence = [0, 1]
        for i in range(2, n):
            next_fib = sequence[i-1] + sequence[i-2]
            sequence.append(next_fib)
        with open("fibonacci_output.txt", "w") as f_out:
            for num in sequence:
                f_out.write(str(num) + "\n")

        with open("fibonacci_summary.txt", "w") as f_summary:
            f_summary.write(f"Generated {n} Fibonacci numbers.")

        return sequence

def capitalize_sentences(text):
    result_lines = []
    with open("temp_input.txt", "w") as f_in:
        f_in.write(text)

    with open("temp_input.txt", "r") as f_read:
        for line in f_read:
            modified_line = ""
            capitalize_next = True
            for char in line:
                if capitalize_next and char.isalpha():
                    modified_line += char.upper()
                    capitalize_next = False
                else:
                    modified_line += char
                if char in ".!?":
                    capitalize_next = True
            result_lines.append(modified_line)

    with open("temp_output.txt", "w") as f_out:
        for line in result_lines:
            f_out.write(line)

    with open("temp_output.txt", "r") as f_final:
        final_text = f_final.read()

    return final_text

def calculate_grade(score):
    with open('grades.txt', 'a') as f:
        f.write(f"Score received: {score}\n")

    if 90 <= score <= 100:
        grade = 'A'
    elif 80 <= score < 90:
        grade = 'B'
    elif 70 <= score < 80:
        grade = 'C'
    elif 60 <= score < 70:
        grade = 'D'
    else:
        grade = 'F'

    with open('grade_output.txt', 'w') as f:
        f.write(f"The grade for score {score} is: {grade}\n")

    with open('grade_summary.txt', 'a') as f:
        f.write(f"{score},{grade}\n")

    with open('latest_grade.txt', 'w') as f:
        f.write(f"Last processed score: {score}, Grade: {grade}\n")

    return grade

